-- ============================================================================
-- PTAS Migration 0052: Central Geographical Identity & Permanent Circles System
-- 
-- 1. Creates core normalized tables:
--    - geo_divisions (10 administrative divisions)
--    - geo_districts (42 districts with PBS codes and collision-free 3-char initials)
--    - geo_tehsils (157 gazetted tehsils with unique codes 1..157)
--    - geo_circles (420 permanent immutable circles: 10 upfront per district)
--    - user_jurisdiction_assignments (decoupled dynamic staff postings)
-- 
-- 2. Seeds:
--    - 10 Divisions
--    - 42 Districts (PBS codes 201..243, unique initials)
--    - 157 Tehsils (Codes 1..157)
--    - 420 Permanent Circles (XXX-1..XXX-10)
-- 
-- 3. Backward Compatibility:
--    - Maps Vehari pilot circles (CIR_VEH_01..10) to VHR-1..VHR-10.
-- ============================================================================

BEGIN;

-- 1. geo_divisions table
CREATE TABLE IF NOT EXISTS public.geo_divisions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  division_code varchar(20) NOT NULL UNIQUE,
  name varchar(100) NOT NULL,
  abbrev varchar(10) NOT NULL UNIQUE,
  headquarter_city varchar(100) NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- 2. geo_districts table
CREATE TABLE IF NOT EXISTS public.geo_districts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  division_id uuid NOT NULL REFERENCES public.geo_divisions(id) ON DELETE RESTRICT,
  pbs_code varchar(3) NOT NULL UNIQUE,
  district_code varchar(3) NOT NULL UNIQUE,
  name varchar(100) NOT NULL,
  full_name varchar(150) NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- 3. geo_tehsils table
CREATE TABLE IF NOT EXISTS public.geo_tehsils (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  district_id uuid NOT NULL REFERENCES public.geo_districts(id) ON DELETE RESTRICT,
  division_id uuid NOT NULL REFERENCES public.geo_divisions(id) ON DELETE RESTRICT,
  tehsil_code int NOT NULL UNIQUE,
  name varchar(100) NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- 4. geo_circles table (Permanent and Immutable)
CREATE TABLE IF NOT EXISTS public.geo_circles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  district_id uuid NOT NULL REFERENCES public.geo_districts(id) ON DELETE RESTRICT,
  division_id uuid NOT NULL REFERENCES public.geo_divisions(id) ON DELETE RESTRICT,
  tehsil_id uuid REFERENCES public.geo_tehsils(id) ON DELETE SET NULL,
  circle_code varchar(10) NOT NULL UNIQUE,
  name varchar(100) NOT NULL,
  circle_number int NOT NULL,
  is_immutable boolean NOT NULL DEFAULT true,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_district_circle_number UNIQUE (district_id, circle_number)
);

-- 5. user_jurisdiction_assignments table (Decoupled staff rotation layer)
CREATE TABLE IF NOT EXISTS public.user_jurisdiction_assignments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.app_users(id) ON DELETE CASCADE,
  role_code text NOT NULL,
  circle_id uuid REFERENCES public.geo_circles(id) ON DELETE SET NULL,
  district_id uuid REFERENCES public.geo_districts(id) ON DELETE SET NULL,
  division_id uuid REFERENCES public.geo_divisions(id) ON DELETE SET NULL,
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_to timestamptz,
  assigned_by uuid REFERENCES public.app_users(id) ON DELETE SET NULL,
  transfer_order_number text,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- Indexes for lightning-fast lookups
CREATE INDEX IF NOT EXISTS idx_geo_districts_division ON public.geo_districts(division_id);
CREATE INDEX IF NOT EXISTS idx_geo_districts_pbs ON public.geo_districts(pbs_code);
CREATE INDEX IF NOT EXISTS idx_geo_districts_code ON public.geo_districts(district_code);

CREATE INDEX IF NOT EXISTS idx_geo_tehsils_district ON public.geo_tehsils(district_id);
CREATE INDEX IF NOT EXISTS idx_geo_tehsils_division ON public.geo_tehsils(division_id);
CREATE INDEX IF NOT EXISTS idx_geo_tehsils_code ON public.geo_tehsils(tehsil_code);

CREATE INDEX IF NOT EXISTS idx_geo_circles_district ON public.geo_circles(district_id);
CREATE INDEX IF NOT EXISTS idx_geo_circles_division ON public.geo_circles(division_id);
CREATE INDEX IF NOT EXISTS idx_geo_circles_code ON public.geo_circles(circle_code);

CREATE INDEX IF NOT EXISTS idx_user_jurisdiction_user ON public.user_jurisdiction_assignments(user_id);
CREATE INDEX IF NOT EXISTS idx_user_jurisdiction_circle ON public.user_jurisdiction_assignments(circle_id);
CREATE INDEX IF NOT EXISTS idx_user_jurisdiction_district ON public.user_jurisdiction_assignments(district_id);
CREATE INDEX IF NOT EXISTS idx_user_jurisdiction_division ON public.user_jurisdiction_assignments(division_id);

-- ----------------------------------------------------------------------------
-- SEED 1: 10 Administrative Divisions
-- ----------------------------------------------------------------------------
ON CONFLICT (division_code) DO UPDATE SET
  name = EXCLUDED.name,
  abbrev = EXCLUDED.abbrev,
  headquarter_city = EXCLUDED.headquarter_city;

-- ----------------------------------------------------------------------------
-- SEED 2: 42 Districts (PBS Codes 201..243 & Collision-Free 3-Char Initials)
-- ----------------------------------------------------------------------------
ON CONFLICT (district_code) DO UPDATE SET
  division_id = EXCLUDED.division_id,
  pbs_code = EXCLUDED.pbs_code,
  name = EXCLUDED.name,
  full_name = EXCLUDED.full_name;

-- ----------------------------------------------------------------------------
-- SEED 3: 157 Gazetted Tehsils (Unique Codes 1..157)
-- ----------------------------------------------------------------------------
ON CONFLICT (tehsil_code) DO UPDATE SET
  district_id = EXCLUDED.district_id,
  division_id = EXCLUDED.division_id,
  name = EXCLUDED.name;

-- ----------------------------------------------------------------------------
-- SEED 4: 420 Permanent Baseline Circles (10 Upfront Per District)
-- ----------------------------------------------------------------------------
ON CONFLICT (circle_code) DO UPDATE SET
  name = EXCLUDED.name,
  circle_number = EXCLUDED.circle_number,
  is_immutable = true;

-- ----------------------------------------------------------------------------
-- SEED 5: Map Vehari Pilot Circles to VHR-1..VHR-10 & Attach Default Tehsils
-- ----------------------------------------------------------------------------
-- Attach Vehari circles to their respective gazetted tehsils in geo_circles
UPDATE public.geo_circles
SET tehsil_id = (SELECT id FROM public.geo_tehsils WHERE tehsil_code = 108) -- Vehari Tehsil
WHERE circle_code IN ('VHR-1', 'VHR-2', 'VHR-5', 'VHR-8', 'VHR-9');

UPDATE public.geo_circles
SET tehsil_id = (SELECT id FROM public.geo_tehsils WHERE tehsil_code = 106) -- Burewala Tehsil
WHERE circle_code IN ('VHR-3', 'VHR-6');

UPDATE public.geo_circles
SET tehsil_id = (SELECT id FROM public.geo_tehsils WHERE tehsil_code = 107) -- Mailsi Tehsil
WHERE circle_code IN ('VHR-4', 'VHR-7', 'VHR-10');

-- ----------------------------------------------------------------------------
-- SEED 6: Synchronize legacy public.jurisdictions hierarchy
-- (Ensures backward compatibility with trigger validate_jurisdiction_hierarchy)
-- ----------------------------------------------------------------------------
-- 6a. Sync Divisions
SELECT gen_random_uuid(), division_code, name, 'DIVISION', NULL, abbrev, name, '{}'::jsonb
FROM public.geo_divisions
ON CONFLICT (code) DO UPDATE SET 
  name = EXCLUDED.name, 
  abbreviation = EXCLUDED.abbreviation,
  display_label = EXCLUDED.display_label;

-- 6b. Sync Districts
SELECT 
  gen_random_uuid(),
  'DIST_' || d.district_code,
  d.name,
  'DISTRICT',
  j_div.id,
  d.district_code,
  d.full_name,
  ('{"pbs_code":"' || d.pbs_code || '"}')::jsonb
FROM public.geo_districts d
JOIN public.geo_divisions div ON d.division_id = div.id
JOIN public.jurisdictions j_div ON j_div.code = div.division_code
ON CONFLICT (code) DO UPDATE SET 
  name = EXCLUDED.name, 
  abbreviation = EXCLUDED.abbreviation,
  display_label = EXCLUDED.display_label, 
  parent_id = EXCLUDED.parent_id,
  external_identifiers = EXCLUDED.external_identifiers;

-- 6c. Sync Tehsils
SELECT 
  gen_random_uuid(),
  'TEH_' || lpad(t.tehsil_code::text, 3, '0'),
  t.name,
  'TEHSIL',
  j_dist.id,
  'T' || lpad(t.tehsil_code::text, 3, '0'),
  'Tehsil ' || t.name,
  ('{"tehsil_code":' || t.tehsil_code || '}')::jsonb
FROM public.geo_tehsils t
JOIN public.geo_districts d ON t.district_id = d.id
JOIN public.jurisdictions j_dist ON j_dist.code = 'DIST_' || d.district_code
ON CONFLICT (code) DO UPDATE SET 
  name = EXCLUDED.name, 
  abbreviation = EXCLUDED.abbreviation,
  display_label = EXCLUDED.display_label, 
  parent_id = EXCLUDED.parent_id,
  external_identifiers = EXCLUDED.external_identifiers;

-- 6d. Sync Circles
SELECT 
  gen_random_uuid(),
  c.circle_code,
  c.name,
  'CIRCLE',
  j_dist.id,
  c.circle_code,
  c.name,
  ('{"circle_code":"' || c.circle_code || '"}')::jsonb
FROM public.geo_circles c
JOIN public.geo_districts d ON c.district_id = d.id
JOIN public.jurisdictions j_dist ON j_dist.code = 'DIST_' || d.district_code
ON CONFLICT (code) DO UPDATE SET 
  name = EXCLUDED.name, 
  abbreviation = EXCLUDED.abbreviation,
  display_label = EXCLUDED.display_label, 
  parent_id = EXCLUDED.parent_id,
  external_identifiers = EXCLUDED.external_identifiers;

COMMIT;
